WITH order_summary AS (SELECT order_id, COUNT(DISTINCT cost) AS unique_statuss, ROUND((100 * SUM(CASE WHEN status = 'LOST' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_lost FROM shipments GROUP BY order_id) SELECT o.id, o.discount, o.shipping_fee, os.unique_statuss, os.pct_lost FROM orders o LEFT OUTER JOIN order_summary os ON o.id = os.order_id WHERE os.unique_statuss >= 9 ORDER BY os.pct_lost ASC
